ST.xhtml:p:
IF fire AND (NOT edge_ir OR (NOT Busy AND (ABS(INT_TO_REAL(pos_target) - tgt) > 0.499))) THEN
    IF pos_target > 100 OR pos_target < 0 THEN
        (* target out of range: no new trajectory, stay put *)
        Done := TRUE;
    ELSE
        tgt := INT_TO_REAL(pos_target);
        Busy := TRUE;
        Done := FALSE;
    END_IF;
END_IF;
edge_ir := fire;

IF hold_req THEN
    IF vel > 0.0 THEN vel := MAX(0.0, vel - ACCEL * SCAN_T);
    ELSIF vel < 0.0 THEN vel := MIN(0.0, vel + ACCEL * SCAN_T);
    END_IF;
ELSIF Busy THEN
    dist := tgt - pos;
    stop_d := (vel * vel) / (2.0 * ACCEL);
    IF ABS(dist) <= stop_d THEN
        IF dist >= 0.0 THEN vel := MAX(0.0, vel - ACCEL * SCAN_T);
        ELSE vel := MIN(0.0, vel + ACCEL * SCAN_T);
        END_IF;
        IF vel = 0.0 AND ABS(dist) <= INT_TO_REAL(POSWIN) THEN
            pos := tgt;
            Busy := FALSE;
            Done := TRUE;
        END_IF;
    ELSE
        IF dist > 0.0 THEN vel := MIN(VMAX, vel + ACCEL * SCAN_T);
        ELSE vel := MAX(-VMAX, vel + ACCEL * SCAN_T);
        END_IF;
    END_IF;
END_IF;

pos := pos + vel * SCAN_T;
Setpoint := REAL_TO_INT(pos);

(* state: 1=SOD 2=RTSO 3=SO 4=OE 5=QSA 6=FRA 7=FA *)
cmd := cw AND 16#000F;

IF state = 7 AND (cw AND 16#0080) <> 0 THEN
    state := 1;
END_IF;

CASE state OF
    1: IF cmd = 16#06 THEN state := 2; END_IF;
    2: IF cmd = 16#07 THEN state := 3;
       ELSIF cmd = 16#0F THEN state := 4;
       ELSIF cmd = 16#00 THEN state := 1;
       END_IF;
    3: IF cmd = 16#0F THEN state := 4;
       ELSIF cmd = 16#06 THEN state := 2;
       ELSIF cmd = 16#00 THEN state := 1;
       ELSIF cmd = 16#02 THEN state := 5;
       END_IF;
    4: IF cmd = 16#07 THEN state := 3;
       ELSIF cmd = 16#06 THEN state := 2;
       ELSIF cmd = 16#00 THEN state := 1;
       ELSIF cmd = 16#02 THEN state := 5;
       END_IF;
    5: IF v_out = 0.0 THEN
           IF cmd = 16#0F THEN state := 4;
           ELSIF cmd = 16#06 THEN state := 2;
           ELSIF cmd = 16#00 THEN state := 1;
           END_IF;
       END_IF;
    6: IF v_out = 0.0 THEN state := 7; END_IF;
END_CASE;

(* position loop: P control + setpoint differential feedforward *)
IF state >= 4 AND state <= 6 THEN
    v_ff := INT_TO_REAL(Setpoint - sp_prev) / SCAN_T;
    pos_err := INT_TO_REAL(Setpoint) - INT_TO_REAL(pos_fb);
    v_out := v_ff + KP * pos_err;
    IF v_out > 120.0 THEN v_out := 120.0; END_IF;
    IF v_out < -120.0 THEN v_out := -120.0; END_IF;
    IF v_ff = 0.0 AND ABS(pos_err) <= 1.5 THEN
        v_out := 0.0;
    END_IF;
ELSIF state = 5 THEN
    IF v_out > 0.0 THEN v_out := MAX(0.0, v_out - QS_DECEL * SCAN_T);
    ELSIF v_out < 0.0 THEN v_out := MIN(0.0, v_out + QS_DECEL * SCAN_T);
    END_IF;
ELSE
    v_out := 0.0;
END_IF;

sp_prev := Setpoint;
v_cmd := REAL_TO_INT(v_out);

sw := 0;
CASE state OF
    1: sw := 16#0040;
    2: sw := 16#0031;
    3: sw := 16#0033;
    4: sw := 16#0037;
    5: sw := 16#0014;
    7: sw := 16#0018;
END_CASE;
IF state = 4 THEN
    IF ABS(pos_err) <= 2.0 AND v_ff = 0.0 THEN
        sw := sw OR 16#0400;
    END_IF;
END_IF;

IF Enable AND pstep = 4 AND (sw AND 16#0004) = 0 AND (sw AND 16#0008) = 0 THEN
    pstep := 0;
END_IF;
IF Enable THEN
    CASE pstep OF
        0: cw := (cw AND 16#00F0) OR 16#0006;  pstep := 1;
        1: IF (sw AND 16#0001) <> 0 THEN cw := (cw AND 16#00F0) OR 16#0007; pstep := 2; END_IF;
        2: IF (sw AND 16#0002) <> 0 THEN cw := (cw AND 16#00F0) OR 16#000F; pstep := 3; END_IF;
        3: IF (sw AND 16#0004) <> 0 THEN pstep := 4; END_IF;
    END_CASE;
ELSE
    cw := (cw AND 16#00F0) OR 16#0006;
    pstep := 0;
END_IF;
Status := (sw AND 16#0004) <> 0;

IF fire AND NOT edge_rs THEN
    busy := TRUE;
END_IF;
edge_rs := fire;
IF busy THEN
    IF (sw AND 16#0008) <> 0 THEN
        cw := cw OR 16#0080;
    ELSE
        cw := cw AND 16#FF7F;
        busy := FALSE;
    END_IF;
END_IF;
Done := NOT busy AND (sw AND 16#0008) = 0 AND NOT fire;

IF fire THEN
    cw := (cw AND 16#00F0) OR 16#0002;
END_IF;

IF fire AND NOT edge_ma THEN
    interp_exe := TRUE;
END_IF;
edge_ma := fire;
Done := NOT interp_exe;
Busy := interp_exe;

IF JogForward AND jog_pos < 97 THEN
    jog_pos := jog_pos + 1;
ELSIF JogBackward AND jog_pos > 3 THEN
    jog_pos := jog_pos - 1;
END_IF;
Busy := JogForward OR JogBackward;

(* ---- program identity ---- *)
prog_id := 2;

(* ---- pen state / fault scan ---- *)
pen_down := (z_fb <= 1);
fault_prev := ((x_sww AND 16#0008) <> 0) OR ((y_sww AND 16#0008) <> 0) OR ((z_sww AND 16#0008) <> 0);
fault_any := fault_prev;

(* ---- draw trigger (C3: requires run + all_oe; C4: no fault) ---- *)
draw_trig := cmd_draw AND (NOT edge_dw) AND run AND all_oe AND (NOT quickstop) AND (NOT fault_prev) AND (pl_step = 0);
edge_dw := cmd_draw;

(* ---- home trigger (Z reference = pen up 10) ---- *)
IF cmd_home AND (NOT edge_hm) AND run AND (NOT quickstop) AND (NOT fault_prev) THEN
    home_exe := TRUE;
END_IF;
edge_hm := cmd_home;
IF home_exe AND ix_z.Done AND (NOT ix_z.Busy) THEN
    home_exe := FALSE;
END_IF;

(* ---- abort sequence on quickstop / fault / run off (C1, C3, C4) ---- *)
IF (quickstop OR fault_prev OR (NOT run)) AND (pl_step <> 0) THEN
    pl_step := 0;
    go_x_exe := FALSE;
    go_y_exe := FALSE;
    go_z_exe := FALSE;
END_IF;
IF quickstop OR fault_prev THEN
    plot_done := FALSE;
END_IF;

(* ---- enable / reset / quickstop (quickstop written last = highest prio) ---- *)
pwr_x(Enable := run AND (NOT quickstop), cw := x_cw, sw := x_sww);
pwr_y(Enable := run AND (NOT quickstop), cw := y_cw, sw := y_sww);
pwr_z(Enable := run AND (NOT quickstop), cw := z_cw, sw := z_sww);
rs_x(fire := cmd_reset, cw := x_cw, sw := x_sww);
rs_y(fire := cmd_reset, cw := y_cw, sw := y_sww);
rs_z(fire := cmd_reset, cw := z_cw, sw := z_sww);
st_x(fire := quickstop, cw := x_cw);
st_y(fire := quickstop, cw := y_cw);
st_z(fire := quickstop, cw := z_cw);

(* ---- manual MC commands, pen interlock C2 (jog / cmd_go blocked while pen_down) ---- *)
gx(fire := cmd_go AND (NOT pen_down) AND run AND (NOT quickstop), interp_exe := gx_exe);
gy(fire := cmd_go AND (NOT pen_down) AND run AND (NOT quickstop), interp_exe := gy_exe);
gz(fire := cmd_go AND (NOT pen_down) AND run AND (NOT quickstop), interp_exe := gz_exe);
jg_x(JogForward := jog_fwd AND (NOT pen_down) AND run AND (NOT quickstop),
     JogBackward := jog_rev AND (NOT pen_down) AND run AND (NOT quickstop),
     jog_pos := x_jog);

(* ---- circle plot sequencer (C5): level-held exe lines, steps only change targets ---- *)
CASE pl_step OF
    0: IF draw_trig THEN
           plot_done := FALSE;
           pz := 10;
           go_z_exe := TRUE;
           pl_step := 1;
       END_IF;
    1: pz := 10;                                   (* ensure pen up *)
    2: px := 50; py := 25;                         (* position to circle start *)
    3: pz := 0;                                    (* pen down *)
    4: IF theta < 4.712389 THEN                    (* full circle: -pi/2 .. 3*pi/2 *)
           theta := theta + 0.0288;                (* 1.44 rad/s = 36 %/s tangential *)
       END_IF;
       IF theta > 4.712389 THEN
           theta := 4.712389;
       END_IF;
       px := 50 + REAL_TO_INT(25.0 * COS(theta));  (* center (50,50), r=25 *)
       py := 50 + REAL_TO_INT(25.0 * SIN(theta));
    5: pz := 10;                                   (* pen up *)
    6: px := 50; py := 50;                         (* return to center *)
END_CASE;

(* ---- step advance on all-relevant-axes done ---- *)
IF pl_step = 1 AND ix_z.Done AND (NOT ix_z.Busy) THEN
    go_z_exe := FALSE;
    px := 50; py := 25;
    go_x_exe := TRUE; go_y_exe := TRUE;
    pl_step := 2;
END_IF;
IF pl_step = 2 AND ix_x.Done AND ix_y.Done AND (NOT ix_x.Busy) AND (NOT ix_y.Busy) THEN
    go_x_exe := FALSE; go_y_exe := FALSE;
    pz := 0; go_z_exe := TRUE;
    pl_step := 3;
END_IF;
IF pl_step = 3 AND ix_z.Done AND (NOT ix_z.Busy) THEN
    go_z_exe := FALSE;
    theta := -1.5707963;
    pl_step := 4;
END_IF;
IF pl_step = 4 AND (theta >= 4.712389) AND ix_x.Done AND ix_y.Done AND (NOT ix_x.Busy) AND (NOT ix_y.Busy) THEN
    pz := 10; go_z_exe := TRUE;
    pl_step := 5;
END_IF;
IF pl_step = 5 AND ix_z.Done AND (NOT ix_z.Busy) THEN
    go_z_exe := FALSE;
    px := 50; py := 50;
    go_x_exe := TRUE; go_y_exe := TRUE;
    pl_step := 6;
END_IF;
IF pl_step = 6 AND ix_x.Done AND ix_y.Done AND (NOT ix_x.Busy) AND (NOT ix_y.Busy) THEN
    go_x_exe := FALSE; go_y_exe := FALSE;
    plot_done := TRUE;
    pl_step := 0;
END_IF;

(* ---- target routing: sequencer targets override NC setpoints when active ---- *)
IF home_exe THEN
    pz := 10;
ELSIF pl_step = 0 THEN
    px := x_sp; py := y_sp; pz := z_sp;
END_IF;

(* ---- interpolators (continuous tracking: target change while fire level-held starts new traj) ---- *)
ix_x(fire := go_x_exe OR gx_exe, pos_target := px, hold_req := FALSE);
ix_y(fire := go_y_exe OR gy_exe, pos_target := py, hold_req := FALSE);
ix_z(fire := go_z_exe OR gz_exe OR home_exe, pos_target := pz, hold_req := FALSE);

IF ix_x.Done AND (NOT ix_x.Busy) THEN go_x_exe := FALSE; gx_exe := FALSE; END_IF;
IF ix_y.Done AND (NOT ix_y.Busy) THEN go_y_exe := FALSE; gy_exe := FALSE; END_IF;
IF ix_z.Done AND (NOT ix_z.Busy) THEN go_z_exe := FALSE; gz_exe := FALSE; END_IF;

(* ---- setpoint routing: jog overrides interp on X ---- *)
IF jg_x.Busy THEN
    x_interp := x_jog;
ELSE
    x_interp := ix_x.Setpoint;
END_IF;
y_interp := ix_y.Setpoint;
z_interp := ix_z.Setpoint;

(* ---- drives: CSP follow + position loop ---- *)
dv_x(cw := x_cw, Setpoint := x_interp, pos_fb := x_fb);
x_sww := dv_x.sw;
x_v := dv_x.v_cmd;
dv_y(cw := y_cw, Setpoint := y_interp, pos_fb := y_fb);
y_sww := dv_y.sw;
y_v := dv_y.v_cmd;
dv_z(cw := z_cw, Setpoint := z_interp, pos_fb := z_fb);
z_sww := dv_z.sw;
z_v := dv_z.v_cmd;
IF z_v > 20 THEN z_v := 20; END_IF;
IF z_v < -20 THEN z_v := -20; END_IF;

(* ---- diagnostic status words ---- *)
x_sw := WORD_TO_INT(x_sww);
y_sw := WORD_TO_INT(y_sww);
z_sw := WORD_TO_INT(z_sww);

(* ---- application status (C6) ---- *)
all_oe := pwr_x.Status AND pwr_y.Status AND pwr_z.Status;
any_moving := (x_v <> 0) OR (y_v <> 0) OR (z_v <> 0);
move_done := gx.Done AND gy.Done AND gz.Done AND (pl_step = 0);

(* ---- C1/C3/C4: force velocity outputs to zero during quickstop / run-off / fault ---- *)
IF quickstop OR (NOT run) OR fault_prev THEN
    x_v := 0;
    y_v := 0;
    z_v := 0;
END_IF;
